11	{% macro actions(v, s, status) -%}
12	  <div class="actions" id="actions-{{ s.id | replace('.', '-') }}">
13	    {{ status_pill(status) }}
14	    {% if status == 'open' and s.body.kind != 'conviction_review' %}
15	      <form method="post" action="/suggestion/{{ s.id }}/accept" hx-post="/suggestion/{{ s.id }}/accept"
16	            hx-target="#actions-{{ s.id | replace('.', '-') }}" hx-swap="outerHTML"><button class="primary">Accept</button></form>
