25	{% macro card(v, s, sizes) -%}
26	  {%- set b = s.body -%}
27	  <div class="panel card">
28	    {% if b.kind == 'existing_thesis' %}
29	      {%- set p = v.pillar(b.pillar_id) -%}
30	      <h3><a href="/suggestion/{{ s.id }}">{{ b.pillar_id }}</a>
31	        <span class="pill {{ b.stance }}">{{ b.stance }}</span>
32	        <span class="pill">strength {{ b.strength }}</span>
33	        {% if b.wrong_if_met %}<span class="pill contradicts">"wrong if" met</span>{% endif %}
34	        {% if s.second_look %}<span class="pill second">second look</span>{% endif %}
35	        <span class="muted small">{{ v.thesis(v.ticker_of(s)).stance }} · {{ sizes.get(v.ticker_of(s)) }} bps</span></h3>
36	      {% if p %}<div class="small muted">{{ p.statement }}</div>{% endif %}
37	      {% for a in b.assumptions %}
38	        <div class="small">Stated {{ a.driver_id }}: <b>{{ a.stated_value | num }}</b>
39	          (book {{ v.driver(a.driver_id).analyst | num if v.driver(a.driver_id) else a.book_value | num }},
40	          consensus {{ a.consensus_value | num }})</div>
41	      {% endfor %}
42	    {% elif b.kind == 'new_thesis' %}
43	      <h3><a href="/suggestion/{{ s.id }}">New thesis for {{ b.ticker }}</a>
44	        {% if s.second_look %}<span class="pill second">second look</span>{% endif %}</h3>
45	      <div>{{ b.statement }}</div>
46	      <div class="small muted">Wrong if: {{ b.wrong_if }}</div>
47	    {% else %}
48	      <h3><a href="/suggestion/{{ s.id }}">Conviction review: {{ b.ticker }}</a></h3>
49	      <div class="small">Accepted contradicting evidence on {{ b.pillar_id }} reached the review threshold.</div>
50	    {% endif %}
51	    <div>{{ s.rationale }}</div>
52	    <div class="small">Linked emails:
53	      {% for eid in v.sections(s) | map(attribute='email_id') | unique %}{{ email_link(v, eid) }}{% if not loop.last %}; {% endif %}{% endfor %}
54	    </div>
55	    {{ actions(v, s, v.status(s)) }}
56	  </div>
